<?php $address=json_decode($order['address_json'],true); ?><div class="admin-toolbar"><a class="text-link" href="<?= e(url('admin/orders')) ?>">← All orders</a><button class="btn btn-outline-primary no-print" onclick="window.print()">Print / save order summary</button></div><?php require ROOT.'/app/Views/store/order-tracking.php'; ?><div class="checkout-grid"><div><section class="panel"><h2>Order items</h2><?php foreach($items as $i): ?><div class="summary-line"><span><?= e($i['name']) ?> · <?= e($i['variant']) ?> × <?= $i['quantity'] ?></span><strong><?= money($i['price']*$i['quantity']) ?></strong></div><?php endforeach ?><hr><?php $totals=$order;require ROOT.'/app/Views/store/summary.php'; ?></section><section class="panel mt-4"><h3>Delivery details</h3><p><?= e($address['name']) ?><br><?= e($address['email']) ?> · <?= e($address['mobile']) ?><br><?= e($address['address']) ?><br><?= e($address['city'].', '.$address['state'].' '.$address['pincode']) ?></p><p><?= e($address['instructions']??'') ?></p></section><section class="panel mt-4"><h3>Payment references</h3><p><?= e($order['payment_method']) ?> · <strong><?= e($order['payment_status']) ?></strong></p><p class="break-all"><?= e($order['razorpay_order_id']) ?></p><?php foreach($payments as $p): ?><p><?= e($p['provider_id']) ?> · <?= money($p['amount']) ?> · <?= e($p['status']) ?></p><?php endforeach ?><?php if($order['payment_method']==='razorpay'): ?><form method="post" action="<?= e(url('admin/order')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><button class="btn btn-outline-primary" name="action" value="sync">Verify payment / refund with Razorpay</button><p class="small muted mt-2">Issue refunds in the Razorpay dashboard. This verifies a full provider-confirmed refund before updating the payment status.</p></form><?php elseif($order['status']==='Delivered' && $order['payment_status']!=='paid'): ?><form method="post" action="<?= e(url('admin/order')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><label>Verified COD collection receipt<input class="form-control" name="receipt" required></label><button class="btn btn-outline-primary" name="action" value="cod-paid">Record collected COD payment</button></form><?php endif ?></section></div><aside class="panel order-summary no-print"><h2>Manage order</h2><form method="post" action="<?= e(url('admin/order')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><label>Order status<select class="form-select" name="status"><?php foreach($orderStatuses as $s): ?><option <?= $order['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select></label><label>Courier name<input class="form-control" name="courier" value="<?= e($order['courier']) ?>"></label><label>Courier tracking link (HTTPS)<input class="form-control" type="url" name="tracking_url" value="<?= e($order['tracking_url']) ?>"></label><label>Estimated delivery date<input class="form-control" type="date" name="expected_delivery" value="<?= e($order['expected_delivery']) ?>"></label><label>Tracking reference<input class="form-control" name="tracking" value="<?= e($order['tracking']) ?>"></label><label>Internal notes<textarea class="form-control" name="notes" rows="5"><?= e($order['notes']) ?></textarea></label><button class="btn btn-primary w-100">Update order</button><p class="small muted mt-3">Payment status is verified separately. Eligible cancellations restore reserved stock once.</p></form></aside></div>

